#!/usr/bin/env node
// Compiles the FSH IG with Sushi, then copies the generated resource JSON
// into packages/fhir-artifacts/generated/ so every consumer imports the compiled
// artifacts from one place rather than out of an app's source tree.
//
// FSH is the single source of truth for SPiER's FHIR shapes. Anything under
// packages/fhir-artifacts/generated/ is a build artifact — gitignored, regenerated by this
// script via `npm run copy-fhir` (also invoked by `predev` / `prebuild`).
//
// The SUSHI compile is slow (~30s), so this script is incremental: it skips the
// compile when the fingerprint recorded in `.copy-fhir-manifest` still matches
// the inputs' content, the produced tree's content and the SUSHI version (see
// the "Staleness check" section below). `--force` always recompiles.

import { spawnSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { dirname, resolve, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { SUSHI_VERSION } from '../../scripts/lib/sushi-version.mjs'
import { retrySync } from '../../scripts/lib/retry.mjs'

const scriptPath = fileURLToPath(import.meta.url)
const __dirname = dirname(scriptPath)
const repoRoot = resolve(__dirname, '..', '..')
const igDir = join(repoRoot, 'ig')
const generatedDir = join(igDir, 'fsh-generated', 'resources')
const destDir = join(repoRoot, 'packages', 'fhir-artifacts', 'generated')

// Inputs that determine the SUSHI output. If none of these change, recompiling
// produces byte-identical artifacts (see the staleness check below).
const fshInputDir = join(igDir, 'input', 'fsh')
const sushiConfig = join(igDir, 'sushi-config.yaml')
// Hand-authored Questionnaire JSON. Not a SUSHI input — SUSHI never reads it —
// but it IS an input to `writeInstrumentItemCodes()`,
// `writeQuestionnaireOrdinals()` and `writeQuestionnaireUrls()` below, so editing
// a Questionnaire has to
// invalidate this script's output. Leaving it out is the bug the phase-2 plan
// flagged in advance: the generated lookup would sit there stale while the
// Questionnaire it was derived from had moved on. ⚠️ For the ordinals that is
// not merely stale metadata — a stale weight scores an instrument wrongly and
// plausibly, with nothing to notice it.
const questionnairesDir = join(repoRoot, 'FHIR-Resources')
// The TypeScript artifacts this script emits.
const carePlanProfilesTsPath = join(destDir, 'care-plan-profiles.generated.ts')
const observationProfilesTsPath = join(destDir, 'observation-profiles.generated.ts')
const instrumentSignaturesTsPath = join(destDir, 'instrument-signatures.generated.ts')
const stageIdsTsPath = join(destDir, 'stage-ids.generated.ts')
const questionnaireOrdinalsTsPath = join(destDir, 'questionnaire-ordinals.generated.ts')
const questionnaireUrlsTsPath = join(destDir, 'questionnaire-urls.generated.ts')
// ⚠️ Every emitted artifact belongs in this list: it is what the staleness
// manifest fingerprints, so one left out would sit stale while its FSH moved on.
const generatedTsPaths = [
  carePlanProfilesTsPath,
  observationProfilesTsPath,
  instrumentSignaturesTsPath,
  stageIdsTsPath,
  questionnaireOrdinalsTsPath,
  questionnaireUrlsTsPath,
]
// Records the fingerprint of the inputs this tree was built from and of the
// tree itself. Deliberately has NO `.json` extension: destDir's consumers
// enumerate it and parse everything matching `*.json` as a FHIR resource
// (check-scenario-resources.mjs:175, and the app's `import.meta.glob`), so a
// `.json` marker here would be handed to a FHIR parser as a resource.
// Gitignored along with the rest of destDir.
const manifestPath = join(destDir, '.copy-fhir-manifest')

// ImplementationGuide is IG manifest metadata, not a domain resource consumed by the app.
const EXCLUDE_PREFIXES = ['ImplementationGuide-']

function log(msg) {
  console.log(`[copy-fhir] ${msg}`)
}

// ---------------------------------------------------------------------------
// Staleness check
// ---------------------------------------------------------------------------
// Why this exists:
//   `predev` runs this script on EVERY `npm run dev`, and the SUSHI FSH compile
//   takes ~30s. But the FSH sources rarely change between dev starts, and SUSHI
//   is deterministic — if no input changed, recompiling produces identical
//   output. So we skip the compile (and the copy) whenever the artifacts the app
//   consumes are already newer than every input that feeds them. This turns the
//   common case (no FSH edits) from a ~30s wait into an instant no-op, while
//   still regenerating automatically the first time after any FSH change.
//
// What counts as an input:
//   - everything under ig/input/fsh/ (the FSH source of truth)
//   - ig/sushi-config.yaml (canonical, version, dependencies — all shape output)
//   - everything under FHIR-Resources/ (the hand-authored Questionnaire JSON that
//     instrument-signatures.generated.ts is derived from). SUSHI does not read
//     this tree, so it was not an input while the only codegen read SUSHI output.
//   - this script itself (its copy/exclude/codegen logic shapes the output too)
//
// What counts as output:
//   - the resource JSON its consumers import (packages/fhir-artifacts/generated/)
//   - the generated TypeScript (care-plan-profiles.generated.ts,
//     instrument-signatures.generated.ts)
//   We deliberately key off these CONSUMED artifacts, not ig/fsh-generated/, so
//   that a cleaned/stale intermediate dir doesn't matter — if the app's inputs
//   are current, there is nothing to do.
//
// Correctness — why this is a CONTENT fingerprint and not mtimes:
//   This check used to compare mtimes: skip when the oldest output postdates the
//   newest input. That is sound locally, where mtimes track edits, and useless
//   anywhere the tree did not come from editing it. In a fresh CI checkout git
//   stamps EVERY file with checkout time, so mtimes carry no information about
//   what changed — which is exactly why `prebuild` passed `--force`, and why
//   `verify` immediately followed a compile with a second, identical one 20s
//   later (measured: 13:12:07→13:12:48, then 13:13:25→13:13:45).
//
//   So the skip decision now rests on a manifest written next to the artifacts,
//   recording three things: the SUSHI version that produced them, a fingerprint
//   of every input's CONTENT, and a fingerprint of the produced tree's content.
//   All three must match to skip, which makes this strictly stronger than the
//   mtime check in both directions:
//     - a touched-but-unchanged input no longer forces a pointless ~40s compile;
//     - a hand-edited, truncated or partially-deleted output no longer passes,
//       whereas under mtimes a late-modified output looked NEWER and so looked
//       fine. (The repo's recurring defect is a check that passes while having
//       verified nothing; an output fingerprint is what stops this being one.)
//     - a tree built by a different SUSHI is rebuilt rather than trusted.
//   A fresh clone has no manifest and no outputs, so it builds.
//
//   `--force` still means what it says everywhere it is advertised (a dozen
//   error messages, README and CLAUDE.md all tell a human to run it): skip no
//   work, recompile unconditionally. `prebuild` no longer needs it — the reason
//   it passed `--force` was distrust of mtimes, and there are no mtimes here now.

function walkFiles(dir) {
  const out = []
  let entries
  try {
    entries = readdirSync(dir, { withFileTypes: true })
  } catch {
    return out // missing dir contributes no files
  }
  for (const entry of entries) {
    const full = join(dir, entry.name)
    if (entry.isDirectory()) out.push(...walkFiles(full))
    else out.push(full)
  }
  return out
}

// Fingerprint a set of files by CONTENT. Paths are made relative to the repo
// root and sorted, so the digest is stable across machines and checkout
// locations, and the path is folded in alongside the bytes so that renaming or
// deleting a file changes the digest even when the surviving bytes do not.
function fingerprintFiles(paths) {
  const hash = createHash('sha256')
  const rels = paths
    .map((p) => [p.replace(repoRoot + '/', ''), p])
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
  for (const [rel, abs] of rels) {
    let bytes
    try {
      bytes = readFileSync(abs)
    } catch {
      continue // vanished mid-walk; the file list it came from is the record
    }
    hash.update(rel)
    hash.update('\0')
    hash.update(createHash('sha256').update(bytes).digest())
  }
  return hash.digest('hex')
}

// Everything whose content determines the generated tree. Kept in one place so
// the "What counts as an input" list above has exactly one implementation.
function inputPaths() {
  return [sushiConfig, scriptPath, ...walkFiles(fshInputDir), ...walkFiles(questionnairesDir)]
}

function inputsFingerprint() {
  // SUSHI's version is part of the inputs' identity: the same FSH compiled by a
  // different SUSHI can legitimately produce different output, so a version bump
  // must invalidate the tree rather than be papered over by matching sources.
  return createHash('sha256')
    .update(`sushi:${SUSHI_VERSION}\n`)
    .update(fingerprintFiles(inputPaths()))
    .digest('hex')
}

// The tree as actually produced, so tampering or truncation is detectable. The
// manifest itself is excluded — it cannot record its own digest.
function outputsFingerprint() {
  return fingerprintFiles(walkFiles(destDir).filter((p) => p !== manifestPath))
}

function writeManifest() {
  // Written LAST, after every emitter, so a manifest existing at all means the
  // whole pipeline ran to completion. A crash part-way leaves no manifest (or a
  // stale one whose output digest no longer matches), and the next run rebuilds.
  writeFileSync(
    manifestPath,
    JSON.stringify(
      { sushiVersion: SUSHI_VERSION, inputs: inputsFingerprint(), outputs: outputsFingerprint() },
      null,
      2,
    ) + '\n',
    'utf8',
  )
}

function isUpToDate() {
  // Every consumed artifact must be present, or there is nothing to trust:
  //   - the copied resource dir (must contain files), and
  //   - every generated TS file.
  // Checking existence explicitly first, rather than letting missing paths drop
  // out of a comparison, is what stops a deleted output (empty destDir, removed
  // generated TS) reading as "up to date" and skipping a rebuild the app needs.
  // Excluding the manifest: a tree holding nothing BUT its own manifest is an
  // empty tree, and must not satisfy a guard whose entire job is to be airtight.
  const destFiles = walkFiles(destDir).filter((p) => p !== manifestPath)
  if (destFiles.length === 0) return false // fresh clone / cleaned tree → build
  if (!generatedTsPaths.every((p) => existsSync(p))) return false // a generated TS deleted → build

  // No inputs found is unexpected (a moved ig/ tree, a bad cwd); rebuild rather
  // than silently skip on a fingerprint taken over nothing.
  if (inputPaths().length === 0) return false

  let manifest
  try {
    manifest = JSON.parse(readFileSync(manifestPath, 'utf8'))
  } catch {
    return false // no manifest, or unreadable → build
  }
  if (manifest?.sushiVersion !== SUSHI_VERSION) return false
  if (manifest?.inputs !== inputsFingerprint()) return false
  if (manifest?.outputs !== outputsFingerprint()) return false
  return true
}

/**
 * How many times to attempt the SUSHI compile before giving up.
 *
 * Retried because SUSHI downloads seven FHIR packages from `packages.fhir.org`
 * on a cold cache, and a few minutes of registry trouble there killed the
 * Cloudflare deploy of the public demo on 2026-09-15 — a failure with nothing
 * to do with the commit being built. `scripts/lib/retry.mjs` has the log
 * excerpt, and the argument for retrying every failure rather than trying to
 * recognise a network one.
 *
 * ⚠️ Overridable so a developer debugging a REAL FSH error can stop paying for
 * two extra compiles (`COPY_FHIR_SUSHI_ATTEMPTS=1 npm run copy-fhir`). A bad
 * value falls back to one attempt rather than zero — `retrySync` guarantees the
 * step runs at least once, because "attempts: 0" quietly skipping the compile
 * would leave `copyResources` copying a tree that was never built.
 */
const SUSHI_ATTEMPTS = Number(process.env.COPY_FHIR_SUSHI_ATTEMPTS) || 3

function runSushi() {
  log('compiling FSH with sushi...')
  // Pinned to SUSHI_VERSION above rather than resolving whatever `fsh-sushi`
  // npx finds — it is no longer a web/ devDependency, so there is no locked
  // local copy for npx to prefer over the registry. Pass igDir as an argument
  // — sushi treats it as the project folder and writes to ig/fsh-generated/.
  //
  // `stdio: 'inherit'` is kept on purpose: a cold compile spends minutes
  // downloading packages, and piping the output to inspect it would hold the
  // whole log until the process exits. That choice is what rules out retrying
  // only on a recognised error string — see scripts/lib/retry.mjs.
  const result = retrySync(
    () =>
      withOk(
        spawnSync('npx', ['-y', `fsh-sushi@${SUSHI_VERSION}`, igDir], {
          stdio: 'inherit',
          shell: process.platform === 'win32',
        }),
      ),
    {
      attempts: SUSHI_ATTEMPTS,
      onRetry: ({ attempt, attempts, waitMs }) =>
        log(
          `sushi failed (attempt ${attempt} of ${attempts}) — retrying in ${waitMs / 1000}s. ` +
            'This is usually packages.fhir.org being slow; a real FSH error will fail again.',
        ),
    },
  )
  if (!result.ok) {
    console.error(
      `[copy-fhir] sushi failed after ${result.attemptsUsed} attempt(s) — aborting copy`,
    )
    process.exit(result.status ?? 1)
  }
  if (result.attemptsUsed > 1) log(`sushi succeeded on attempt ${result.attemptsUsed}`)
}

/**
 * Adapt a `spawnSync` result to what `retrySync` reads.
 *
 * ⚠️ `status` is null when the process was killed by a signal or never
 * spawned at all, so "status !== 0" is the test rather than "status" being
 * truthy — a null status is a failure, and reading it as success would march
 * on to copy a tree SUSHI never wrote.
 */
function withOk(result) {
  return { ...result, ok: result.status === 0 }
}

function clearDest() {
  try {
    rmSync(destDir, { recursive: true, force: true })
  } catch {
    // ignore
  }
  mkdirSync(destDir, { recursive: true })
}

function copyResources() {
  let entries
  try {
    entries = readdirSync(generatedDir)
  } catch (err) {
    console.error(`[copy-fhir] expected ${generatedDir} to exist after sushi; got ${err.message}`)
    process.exit(1)
  }

  let copied = 0
  let skipped = 0
  for (const name of entries) {
    if (!name.endsWith('.json')) continue
    if (EXCLUDE_PREFIXES.some((p) => name.startsWith(p))) {
      skipped += 1
      continue
    }
    const src = join(generatedDir, name)
    if (!statSync(src).isFile()) continue
    copyFileSync(src, join(destDir, name))
    copied += 1
  }
  log(`copied ${copied} resource(s) to packages/fhir-artifacts/generated/ (skipped ${skipped})`)
}

/**
 * Emit a TypeScript file declaring the union of canonical URLs for every SPiER
 * StructureDefinition that constrains one resource type. A mapper uses the union
 * to type its `meta.profile` claim — FSH stays the single source of truth, and a
 * mistyped canonical is a compile error rather than a resource claiming a
 * profile nobody published.
 *
 * ⚠️ **The Observation union is why this is parameterized.** It was a CarePlan-
 * only generator while the instrument mappers stamped no profile at all, which
 * meant ~80 of the Observations the app emits validated against base
 * `Observation` — and `validate-fhir.mjs` cannot flag that, because an unclaimed
 * profile degrades to a PASS. The gap was invisible until `check:outputs`
 * related the IG's declared outputs to what the app emits.
 */
function writeProfileUrlUnion({ fhirType, constName, typeName, outPath, sourceNote }) {
  const sdFiles = readdirSync(destDir).filter(
    (n) => n.startsWith('StructureDefinition-') && n.endsWith('.json'),
  )
  const urls = []
  for (const name of sdFiles) {
    const doc = JSON.parse(readFileSync(join(destDir, name), 'utf8'))
    if (doc.kind === 'resource' && doc.type === fhirType && typeof doc.url === 'string') {
      urls.push(doc.url)
    }
  }
  urls.sort()

  const lines = [
    '// Auto-generated by web/scripts/copy-fhir.mjs — do not edit by hand.',
    `// Source: ${sourceNote}`,
    '// Regenerated on every `npm run copy-fhir` (also runs as predev / prebuild).',
    '',
    `export const ${constName} = [`,
    // Single-quoted to satisfy the repo's @stylistic/quotes rule — this file is
    // emitted into src/ and therefore linted.
    ...urls.map((u) => `  '${u.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}',`),
    '] as const',
    '',
    `export type ${typeName} = (typeof ${constName})[number]`,
    '',
  ]
  // `recursive: true` is idempotent — guards against the rare case where
  // the catalog directory has been deleted (e.g., partial clone, manual rm).
  mkdirSync(destDir, { recursive: true })
  writeFileSync(outPath, lines.join('\n'), 'utf8')
  log(`emitted ${outPath.replace(repoRoot + '/', '')} with ${urls.length} ${fhirType} profile URL(s)`)
}

function writeCarePlanProfileTypes() {
  writeProfileUrlUnion({
    fhirType: 'CarePlan',
    constName: 'CAREPLAN_PROFILE_URLS',
    typeName: 'CarePlanProfileUrl',
    outPath: carePlanProfilesTsPath,
    sourceNote: 'ig/input/fsh/<tool>.fsh (Profile: ... Parent: CarePlan).',
  })
  writeProfileUrlUnion({
    fhirType: 'Observation',
    constName: 'OBSERVATION_PROFILE_URLS',
    typeName: 'ObservationProfileUrl',
    outPath: observationProfilesTsPath,
    sourceNote: 'ig/input/fsh/<tool>.fsh (Profile: ... Parent: Observation).',
  })
}

/**
 * Emit a TypeScript lookup of `canonical → linkId → the codings that
 * Questionnaire item declares`, read out of the hand-authored Questionnaire JSON
 * in FHIR-Resources/.
 *
 * Why: `packages/core/src/lib/observationMappers/fallbackDispatch.ts` recognizes
 * a foreign QuestionnaireResponse from standardized (LOINC) per-item codes. It
 * used to hand-list those codes — a third home for a value already living in the
 * Questionnaire and in the mappers — with `check-fallback-signatures.mjs`
 * existing solely to assert the copy still matched. Deriving the codes deletes
 * both the copy and the gate.
 *
 * What stays hand-authored, and why: the signature table's *curatorial*
 * decisions — which instruments get a signature at all, which linkIds belong to
 * each and in what order (Tier-3 positional mapping reads that order),
 * `minCodeMatches`, `answerKind`. Those are judgements with reasons recorded
 * beside them, and several are deliberate EXCLUSIONS of codes this file emits:
 * C-SSRS `actual-lethality`, the shared `risk-level` result code, and the whole
 * of ASQ. A generator that emitted signatures rather than a lookup would silently
 * put all three back. So this emits only the mechanical half — "what code does
 * this Questionnaire currently put on this linkId" — and `fallbackDispatch.ts`
 * names the linkIds it wants.
 *
 * Codes are emitted as an ARRAY per linkId because a Questionnaire item may carry
 * more than one (`item.code` is 0..*), which is also how the deleted gate modelled
 * it. No item in the repo carries two today; the consumer refuses to guess if one
 * ever does, rather than this script picking silently.
 */
function writeInstrumentItemCodes() {
  const stripVersion = (canonical) => {
    const pipe = canonical.indexOf('|')
    return pipe === -1 ? canonical : canonical.slice(0, pipe)
  }

  function* walkItems(items) {
    for (const it of items ?? []) {
      yield it
      yield* walkItems(it.item)
    }
  }

  // canonical (version-stripped) → Map(linkId → [{ system, code }]), for items
  // that carry a code at all. An item with no `code` contributes nothing: the
  // lookup answers "what standardized code names this item", and the answer for
  // an uncoded item is "none", not "an empty list".
  const byCanonical = new Map()
  const sourceOf = new Map()
  for (const file of walkFiles(questionnairesDir)) {
    if (!file.endsWith('.json')) continue
    let doc
    try {
      doc = JSON.parse(readFileSync(file, 'utf8'))
    } catch {
      continue // not JSON we can read — other gates own malformed FHIR
    }
    if (doc?.resourceType !== 'Questionnaire' || typeof doc.url !== 'string') continue
    const canonical = stripVersion(doc.url)
    const rel = file.replace(repoRoot + '/', '')
    if (byCanonical.has(canonical)) {
      // Two Questionnaires on one canonical is the #217 collision class; the
      // last writer would otherwise win in silence. See CLAUDE.md "One canonical
      // URL, one definition".
      console.error(
        `[copy-fhir] two Questionnaires declare canonical "${canonical}": ` +
          `${sourceOf.get(canonical)} and ${rel}`,
      )
      process.exit(1)
    }
    sourceOf.set(canonical, rel)

    const linkIdCodes = new Map()
    for (const it of walkItems(doc.item)) {
      if (!it.linkId) continue
      const codings = (it.code ?? [])
        .filter((c) => typeof c?.code === 'string')
        .map((c) => ({ system: typeof c.system === 'string' ? c.system : '', code: c.code }))
      if (codings.length) linkIdCodes.set(it.linkId, codings)
    }
    byCanonical.set(canonical, linkIdCodes)
  }

  if (byCanonical.size === 0) {
    // Reading nothing must not pass as "nothing to emit" — that is the #232/#261
    // failure mode, and here it would empty the lookup and take every signature's
    // itemCodes with it.
    console.error(
      `[copy-fhir] found no Questionnaires under ${questionnairesDir.replace(repoRoot + '/', '')} — refusing to emit an empty lookup`,
    )
    process.exit(1)
  }

  const q = (s) => `'${String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`
  const lines = [
    '// Auto-generated by web/scripts/copy-fhir.mjs — do not edit by hand.',
    '// Source: FHIR-Resources/<tool>/*.json (Questionnaire.item[].code), keyed by',
    '// version-stripped Questionnaire.url.',
    '// Regenerated on every `npm run copy-fhir` (also runs as predev / prebuild).',
    '//',
    '// Consumed by packages/core/src/lib/observationMappers/fallbackDispatch.ts, which',
    '// names the linkIds each instrument signature covers and resolves their codes',
    '// here. The curatorial decisions — which instruments, which linkIds, in what',
    '// order — live there, not in this file.',
    '',
    'export const QUESTIONNAIRE_ITEM_CODES = {',
  ]
  let itemCount = 0
  for (const canonical of [...byCanonical.keys()].sort()) {
    const linkIdCodes = byCanonical.get(canonical)
    // A Questionnaire whose items carry no codes at all still appears, so the
    // absence is visible rather than looking like a Questionnaire this script
    // failed to read. Its `CodedLinkId` is `never`, so a signature cannot name
    // one of its linkIds.
    if (linkIdCodes.size === 0) {
      lines.push(`  ${q(canonical)}: {},`)
      continue
    }
    lines.push(`  ${q(canonical)}: {`)
    for (const linkId of [...linkIdCodes.keys()].sort()) {
      const codings = linkIdCodes
        .get(linkId)
        .map((c) => `{ system: ${q(c.system)}, code: ${q(c.code)} }`)
        .join(', ')
      lines.push(`    ${q(linkId)}: [${codings}],`)
      itemCount += 1
    }
    lines.push('  },')
  }
  lines.push(
    '} as const',
    '',
    '/** A Questionnaire canonical this lookup knows about. */',
    'export type QuestionnaireCanonical = keyof typeof QUESTIONNAIRE_ITEM_CODES',
    '',
    '/**',
    ' * A linkId that carries a code on the Questionnaire at `C`. Naming one that',
    ' * does not is a type error at every call site — which is what replaced the',
    ' * deleted check:fallback gate.',
    ' */',
    'export type CodedLinkId<C extends QuestionnaireCanonical> =',
    '  keyof (typeof QUESTIONNAIRE_ITEM_CODES)[C] & string',
    '',
  )

  mkdirSync(destDir, { recursive: true })
  writeFileSync(instrumentSignaturesTsPath, lines.join('\n'), 'utf8')
  log(
    `emitted ${instrumentSignaturesTsPath.replace(repoRoot + '/', '')} with ` +
      `${itemCount} coded item(s) across ${byCanonical.size} Questionnaire(s)`,
  )
}

/**
 * Emit a literal-union type of SPiER pathway stage ids, read out of the
 * compiled `SPiERPathwayStage` CodeSystem (`ig/input/fsh/spier-codesystem.fsh`
 * is the source of truth; SUSHI compiles it to
 * `CodeSystem-spier-pathway-stage.json`, already copied into `destDir` by
 * `copyResources()` above by the time this runs).
 *
 * Why: several hand-authored TypeScript tables key or value on a stage id
 * (`CAREPLAN_PROFILE_STAGES`, `STAGE_BLURB`, `StageTrigger.fromStageId` /
 * `toStageId`, `Tool.stageId`) and were typed as bare `string`, so a typo in
 * one of them was invisible at compile time. This is the same fix as
 * `writeCarePlanProfileTypes()` above, one level over: a generated union lets
 * those tables catch a typo AND a missing entry for a newly-added stage as a
 * compile error instead of silent wrong behavior.
 */
/**
 * Emit a TypeScript lookup of `canonical → linkId → the ordinal-weighted answer
 * options that Questionnaire item declares`, read out of FHIR-Resources/.
 *
 * Why this exists, and why it is not just another convenience: the SDC
 * `weight()` join (`ordinalForAnswer` / `answerCodingForOrdinal`) needs three
 * fields per answer option — code, the ordinal, and the coding to rebuild — and
 * nothing else. It used to get them by reaching into the *whole* Questionnaire
 * through `QUESTIONNAIRE_BY_URL`, which put all 18 hand-authored Questionnaire
 * JSON files on the import graph of `packages/core/src/lib/observationMappers/`.
 * Those mappers are reachable from the registry and the measure engine, which
 * are eager — so **166.8 KB of form JSON compiled into the entry chunk of both
 * surfaces**, including the clinical one an EHR frames, and was paid by every
 * visitor whether or not they ever opened a form
 * (`docs/plans/tool-bundling-audit-2026-09-19.md` §5.1).
 *
 * ⚠️ **This is a derived table and must stay derived.** The ordinals are the
 * scores an instrument is summed from; a hand-maintained copy is exactly the
 * drift-prone hand-duplicated value CLAUDE.md warns about, and it would drift
 * silently — a wrong weight produces a plausible total, not an error. There is
 * no gate asserting the copy matches, and there deliberately is not one: the
 * copy is regenerated from the Questionnaires on every `copy-fhir`, and
 * `FHIR-Resources/` is already inside the manifest's input fingerprint, so
 * editing an `ordinalValue` rebuilds this file by the same mechanism that
 * rebuilds the SUSHI tree. A gate would be asserting that a generator ran.
 *
 * Only items with at least one ordinal-bearing option appear. An item whose
 * options carry no `ordinalValue` contributes nothing, because the lookup
 * answers "what weight does this answer score" and the answer is "none".
 */
function writeQuestionnaireOrdinals() {
  const ORDINAL_VALUE_URL = 'http://hl7.org/fhir/StructureDefinition/ordinalValue'
  const stripVersion = (canonical) => {
    const pipe = canonical.indexOf('|')
    return pipe === -1 ? canonical : canonical.slice(0, pipe)
  }
  function* walkItems(items) {
    for (const it of items ?? []) {
      yield it
      yield* walkItems(it.item)
    }
  }

  // canonical → Map(linkId → [{ code, ordinal, system, display }])
  const byCanonical = new Map()
  for (const file of walkFiles(questionnairesDir)) {
    if (!file.endsWith('.json')) continue
    let doc
    try {
      doc = JSON.parse(readFileSync(file, 'utf8'))
    } catch {
      continue // not JSON we can read — other gates own malformed FHIR
    }
    if (doc?.resourceType !== 'Questionnaire' || typeof doc.url !== 'string') continue
    // A canonical collision is already a hard error in writeInstrumentItemCodes,
    // which reads the same directory in the same run, so it cannot reach here.
    const linkIdOptions = new Map()
    for (const it of walkItems(doc.item)) {
      if (!it.linkId) continue
      const options = []
      for (const opt of it.answerOption ?? []) {
        const ext = (opt.extension ?? []).find((e) => e?.url === ORDINAL_VALUE_URL)
        if (typeof ext?.valueDecimal !== 'number') continue
        const coding = opt.valueCoding
        if (typeof coding?.code !== 'string') continue
        options.push({
          code: coding.code,
          ordinal: ext.valueDecimal,
          system: typeof coding.system === 'string' ? coding.system : undefined,
          display: typeof coding.display === 'string' ? coding.display : undefined,
        })
      }
      if (options.length) linkIdOptions.set(it.linkId, options)
    }
    if (linkIdOptions.size) byCanonical.set(stripVersion(doc.url), linkIdOptions)
  }

  if (byCanonical.size === 0) {
    // Reading nothing must not pass as "nothing to emit" — the #232/#261 failure
    // mode. Here it would empty the weight table, and every ordinal-scored
    // instrument would quietly score zero.
    console.error(
      `[copy-fhir] found no ordinal-weighted answer options under ` +
        `${questionnairesDir.replace(repoRoot + '/', '')} — refusing to emit an empty weight table`,
    )
    process.exit(1)
  }

  const q = (s) => `'${String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`
  const lines = [
    '// Auto-generated by web/scripts/copy-fhir.mjs — do not edit by hand.',
    '// Source: FHIR-Resources/<tool>/*.json (Questionnaire.item[].answerOption with',
    '// an SDC ordinalValue extension), keyed by version-stripped Questionnaire.url.',
    '// Regenerated on every `npm run copy-fhir` (also runs as predev / prebuild).',
    '//',
    '// Consumed by packages/core/src/data/questionnaireOrdinals.ts, which is the SDC',
    '// weight() join. It exists so the observation mappers can score an answer',
    '// WITHOUT importing the 18 whole Questionnaires — see that file, and',
    '// docs/plans/tool-bundling-audit-2026-09-19.md §5.1.',
    '',
    'export const QUESTIONNAIRE_ORDINALS = {',
  ]
  let optionCount = 0
  for (const canonical of [...byCanonical.keys()].sort()) {
    lines.push(`  ${q(canonical)}: {`)
    const linkIdOptions = byCanonical.get(canonical)
    for (const linkId of [...linkIdOptions.keys()].sort()) {
      const opts = linkIdOptions
        .get(linkId)
        .map((o) => {
          const parts = [`code: ${q(o.code)}`, `ordinal: ${o.ordinal}`]
          if (o.system) parts.push(`system: ${q(o.system)}`)
          if (o.display) parts.push(`display: ${q(o.display)}`)
          return `{ ${parts.join(', ')} }`
        })
        .join(', ')
      lines.push(`    ${q(linkId)}: [${opts}],`)
      optionCount += linkIdOptions.get(linkId).length
    }
    lines.push('  },')
  }
  lines.push('} as const', '')

  mkdirSync(destDir, { recursive: true })
  writeFileSync(questionnaireOrdinalsTsPath, lines.join('\n'), 'utf8')
  log(
    `emitted ${questionnaireOrdinalsTsPath.replace(repoRoot + '/', '')} with ` +
      `${optionCount} weighted option(s) across ${byCanonical.size} Questionnaire(s)`,
  )
}

/**
 * Emit `Questionnaire.id → canonical url` for every hand-authored Questionnaire.
 *
 * Why a generated map of eighteen strings rather than eighteen literals in
 * `packages/tool-views/src/data/toolViews.tsx`: that file names one Questionnaire
 * per filler entry, and it used to name it by importing the *resource*. Holding
 * 18 resolved resources at module scope is what put 166.8 KB of form JSON into
 * the entry chunk of both surfaces — `App.tsx` imports `TOOL_VIEWS` statically,
 * so every Questionnaire it referenced was eager even though every view
 * component is lazy (`docs/plans/tool-bundling-audit-2026-09-19.md` §5.1).
 *
 * Passing the canonical instead defers the resource to `QuestionnaireView`, which
 * is lazy. But a canonical typed into the map by hand would be the drift-prone
 * hand-duplicated value CLAUDE.md warns about — and a wrong one fails at runtime
 * as "unknown questionnaire", not at build. So it is derived, and
 * `QuestionnaireId` makes naming one that does not exist a type error.
 *
 * ⚠️ Keyed by `Questionnaire.id`, which the IG publisher already requires to
 * equal the canonical's last segment (CLAUDE.md, `FHIR-Resources/`), so the key
 * is not a second naming scheme.
 */
function writeQuestionnaireUrls() {
  const byId = new Map()
  for (const file of walkFiles(questionnairesDir)) {
    if (!file.endsWith('.json')) continue
    let doc
    try {
      doc = JSON.parse(readFileSync(file, 'utf8'))
    } catch {
      continue
    }
    if (doc?.resourceType !== 'Questionnaire') continue
    if (typeof doc.url !== 'string' || typeof doc.id !== 'string') {
      console.error(
        `[copy-fhir] ${file.replace(repoRoot + '/', '')} is a Questionnaire with no ` +
          `${typeof doc.url === 'string' ? 'id' : 'url'} — both are required to key this map`,
      )
      process.exit(1)
    }
    byId.set(doc.id, doc.url.indexOf('|') === -1 ? doc.url : doc.url.slice(0, doc.url.indexOf('|')))
  }

  if (byId.size === 0) {
    // Same non-empty guard as its siblings: emitting {} here would make every
    // filler's questionnaireUrl a type error, which reads as 18 broken views
    // rather than as "the generator read nothing".
    console.error(
      `[copy-fhir] found no Questionnaires under ${questionnairesDir.replace(repoRoot + '/', '')} ` +
        '— refusing to emit an empty url map',
    )
    process.exit(1)
  }

  const q = (s) => `'${String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`
  const lines = [
    '// Auto-generated by web/scripts/copy-fhir.mjs — do not edit by hand.',
    '// Source: FHIR-Resources/<tool>/*.json (Questionnaire.id → Questionnaire.url).',
    '// Regenerated on every `npm run copy-fhir` (also runs as predev / prebuild).',
    '//',
    '// Consumed by packages/tool-views/src/data/toolViews.tsx so the filler entries can',
    '// name a Questionnaire WITHOUT importing one — see that file, and',
    '// docs/plans/tool-bundling-audit-2026-09-19.md §5.1.',
    '',
    'export const QUESTIONNAIRE_URLS = {',
    ...[...byId.keys()].sort().map((id) => `  ${q(id)}: ${q(byId.get(id))},`),
    '} as const',
    '',
    '/** A hand-authored Questionnaire, by id. Naming one that does not exist is a type error. */',
    'export type QuestionnaireId = keyof typeof QUESTIONNAIRE_URLS',
    '',
  ]

  mkdirSync(destDir, { recursive: true })
  writeFileSync(questionnaireUrlsTsPath, lines.join('\n'), 'utf8')
  log(
    `emitted ${questionnaireUrlsTsPath.replace(repoRoot + '/', '')} with ` +
      `${byId.size} Questionnaire canonical(s)`,
  )
}

function writeStageIdType() {
  const codeSystemPath = join(destDir, 'CodeSystem-spier-pathway-stage.json')
  if (!existsSync(codeSystemPath)) {
    console.error(`[copy-fhir] expected ${codeSystemPath.replace(repoRoot + '/', '')} to exist — refusing to emit stage-ids.generated.ts`)
    process.exit(1)
  }

  let doc
  try {
    doc = JSON.parse(readFileSync(codeSystemPath, 'utf8'))
  } catch (err) {
    console.error(`[copy-fhir] ${codeSystemPath.replace(repoRoot + '/', '')} is not valid JSON: ${err.message}`)
    process.exit(1)
  }

  const concepts = Array.isArray(doc?.concept) ? doc.concept : []
  const codes = concepts.filter((c) => typeof c?.code === 'string').map((c) => c.code)
  if (codes.length === 0) {
    // Reading nothing must not pass as "nothing to emit" — the #232/#261
    // failure mode: every consumer of StageId would end up with `never`,
    // which would fail loudly elsewhere, but only after silently emitting an
    // empty union here first.
    console.error(
      `[copy-fhir] ${codeSystemPath.replace(repoRoot + '/', '')} has zero concept entries — refusing to emit an empty StageId union`,
    )
    process.exit(1)
  }

  const q = (s) => `'${String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`
  const lines = [
    '// Auto-generated by web/scripts/copy-fhir.mjs — do not edit by hand.',
    '// Source: ig/input/fsh/spier-codesystem.fsh (CodeSystem: SPiERPathwayStage).',
    '// Regenerated on every `npm run copy-fhir` (also runs as predev / prebuild).',
    '',
    'export const STAGE_IDS = [',
    ...codes.map((c) => `  ${q(c)},`),
    '] as const',
    '',
    'export type StageId = (typeof STAGE_IDS)[number]',
    '',
    '/** Type guard for deriving a StageId from a plain string that is not already known-safe. */',
    'export function isStageId(x: string): x is StageId {',
    '  return (STAGE_IDS as readonly string[]).includes(x)',
    '}',
    '',
  ]

  mkdirSync(destDir, { recursive: true })
  writeFileSync(stageIdsTsPath, lines.join('\n'), 'utf8')
  log(`emitted ${stageIdsTsPath.replace(repoRoot + '/', '')} with ${codes.length} stage id(s)`)
}

/**
 * Print the inputs fingerprint and exit — the CI cache key for the generated
 * tree.
 *
 * Exists so the key has ONE definition. Spelling the input set out as
 * `hashFiles('ig/input/fsh/**', 'FHIR-Resources/**', …)` in the workflow would
 * re-state, in YAML, the list this script's own "What counts as an input"
 * section already owns — in several jobs at once, with nothing comparing the
 * copies. That is the hand-copied-list failure this repo keeps paying for (the
 * stale check:codings floor, the drifted CI step list). A key that comes from
 * `inputsFingerprint()` cannot disagree with the staleness check that consumes
 * the cache, because it IS the staleness check's fingerprint.
 *
 * Uses node builtins only (as does the whole script), so a workflow can call it
 * before `npm ci`.
 */
if (process.argv.includes('--print-input-fingerprint')) {
  process.stdout.write(inputsFingerprint() + '\n')
  process.exit(0)
}

const force = process.argv.includes('--force')
/**
 * Copy an ALREADY-COMPILED ig/fsh-generated into packages/fhir-artifacts/generated/, without
 * invoking sushi.
 *
 * For CI jobs that download `fsh-generated` as an artifact — ig.yml's `validate`
 * job does exactly that, and its own comment says the point is to "reuse the
 * compile from the `sushi` job rather than paying for it twice". Added for #302,
 * whose runtime emitter imports the generated CodeSystems and so needs the copy
 * step, but has no reason to recompile.
 */
const noCompile = process.argv.includes('--no-compile')
if (noCompile) {
  if (!existsSync(generatedDir)) {
    console.error(
      `[copy-fhir] --no-compile needs ${generatedDir.replace(repoRoot + '/', '')} to exist ` +
        'already (download the fsh-generated artifact, or drop --no-compile).',
    )
    process.exit(1)
  }
  clearDest()
  copyResources()
  writeCarePlanProfileTypes()
  writeInstrumentItemCodes()
  writeQuestionnaireOrdinals()
  writeQuestionnaireUrls()
  writeStageIdType()
  // This tree is as legitimate as a compiled one — it came from the same SUSHI
  // output, just downloaded as an artifact instead of produced here — so record
  // it, and let a later plain `copy-fhir` in the same job skip.
  writeManifest()
  process.exit(0)
}
if (!force && isUpToDate()) {
  log('FHIR artifacts are up to date with their sources — skipping SUSHI compile.')
  log('(Edit any .fsh, sushi-config.yaml or FHIR-Resources/ file to trigger a rebuild, or run with --force.)')
  process.exit(0)
}

runSushi()
clearDest()
copyResources()
writeCarePlanProfileTypes()
writeInstrumentItemCodes()
writeQuestionnaireOrdinals()
writeQuestionnaireUrls()
writeStageIdType()
writeManifest()
